export const SEITEN_ZAHL = Math.max(1, Math.ceil(FOLGEN.length / PRO_SEITE));

/** 1-basiert. Seite 1 = /pages/podcasts, ab 2 = /pages/podcasts/seite-N. */
export function seitenPfad(nr) {
  return nr <= 1 ? '/pages/podcasts' : `/pages/podcasts/seite-${nr}`;
}

/** Umkehrung von seitenPfad für das URL-Segment: 'seite-3' -> 3, sonst null.
 *  Streng mit Absicht: 'seite-03' und 'seite-3x' ergeben null, damit nicht
 *  mehrere Schreibweisen denselben Inhalt unter verschiedenen URLs zeigen.
 *  Lebt hier statt in der Route, damit `node --test` die Regel ohne Bundler
 *  prüfen kann (eine Route importiert CSS und ~-Aliase). */
export function nummerAusSegment(segment) {
  const m = /^seite-(\d{1,3})$/.exec(String(segment == null ? '' : segment));
  if (!m) return null;
  const nr = Number(m[1]);
  return String(nr) === m[1] ? nr : null;
}

/** '2026-07-02' + Sekunden -> lesbare deutsche Angaben. */
export function dauerText(sekunden) {
  const std = Math.floor(sekunden / 3600);
  const min = Math.round((sekunden % 3600) / 60);
  return std > 0 ? `${std} Std. ${min} Min.` : `${min} Min.`;
}

export function datumText(iso) {
  const [j, m, t] = iso.split('-');
  return `${t}.${m}.${j}`;
}

/** Folgen einer Seite + Navigationsdaten. Wirft nie: unbekannte Nummern
 *  werden in den gültigen Bereich geklemmt, die Route entscheidet über 404. */
export function seite(nr) {
  const n = Math.min(Math.max(1, nr | 0), SEITEN_ZAHL);
  const von = (n - 1) * PRO_SEITE;
  return {
    nr: n,
    folgen: FOLGEN.slice(von, von + PRO_SEITE),
    gesamt: FOLGEN.length,
    seitenZahl: SEITEN_ZAHL,
    vorher: n > 1 ? seitenPfad(n - 1) : null,
    nachher: n < SEITEN_ZAHL ? seitenPfad(n + 1) : null,
  };
}

/** Beschreibung für das Schema: der erste TRAGFAEHIGE Absatz, nicht blind
 *  der erste. Manche Folgen öffnen mit einem Einzeiler ("Das ist die kurze
 *  Version.") — als Suchergebnis-Text ist das wertlos. Faellt alles aus,
 *  bleibt der Titel, damit das Pflichtfeld nie leer ist. */
export function beschreibung(f) {
  const tragfaehig = f.txt.find((a) => a.length >= 120);
  if (tragfaehig) return tragfaehig;
  const laengster = f.txt.slice().sort((a, b) => b.length - a.length)[0];
  return laengster || f.t;
}

/** JSON-LD @graph: CollectionPage + BreadcrumbList + ItemList(VideoObject).
 *  Clip-Knoten je Kapitelmarke — dieselbe Struktur, die auf dem US-Shop
 *  maschinell gegen Pflichtfelder geprueft wurde. */
export function schemaGraph(daten, basis) {
  const seiteUrl = basis + seitenPfad(daten.nr);
  const videos = daten.folgen.map((f, i) => ({
    '@type': 'VideoObject',
    position: (daten.nr - 1) * PRO_SEITE + i + 1,
    name: f.t,
    description: beschreibung(f),
    thumbnailUrl: f.thumb,
    uploadDate: f.d,
    duration: f.iso,
    embedUrl: `https://www.youtube-nocookie.com/embed/${f.id}`,
    contentUrl: `https://www.youtube.com/watch?v=${f.id}`,
    url: `${seiteUrl}#folge-${f.slug}`,
    inLanguage: f.lang,
    publisher: {'@type': 'Organization', name: 'Qi Blanco', url: basis},
    creator: {'@type': 'Organization', name: 'Qi Blanco', url: basis},
    ...(f.kap.length
      ? {
          hasPart: f.kap.map((k) => ({
            '@type': 'Clip',
            name: k[1],
            startOffset: k[0],
            url: `https://www.youtube.com/watch?v=${f.id}&t=${k[0]}`,
          })),
        }
      : {}),
  }));
  return {
    '@context': 'https://schema.org',
    '@graph': [
      {
        '@type': 'CollectionPage',
        '@id': seiteUrl,
        url: seiteUrl,
        name: 'Podcasts von Qi Blanco',
        inLanguage: 'de',
        isPartOf: {'@type': 'WebSite', url: basis, name: 'Qi Blanco'},
      },
      {
        '@type': 'BreadcrumbList',
        itemListElement: [
          {'@type': 'ListItem', position: 1, name: 'Startseite', item: basis},
          {'@type': 'ListItem', position: 2, name: 'Podcasts', item: basis + '/pages/podcasts'},
          ...(daten.nr > 1
            ? [{'@type': 'ListItem', position: 3, name: `Seite ${daten.nr}`, item: seiteUrl}]
            : []),
        ],
      },
      {
        '@type': 'ItemList',
        name: `Podcast-Folgen, Seite ${daten.nr} von ${daten.seitenZahl}`,
        numberOfItems: daten.folgen.length,
        itemListElement: videos,
      },
    ],
  };
}

/** Alles, was beide Routen brauchen — damit die Routen selbst duenn bleiben
 *  und Seite 1 und Seite N nachweislich denselben Aufbau liefern.
 *
 *  `basis` MUSS CANONICAL_ORIGIN sein, NICHT der Request-Host: auf einem
 *  Oxygen-Preview-Host würde ein Request-basiertes @id/url die Preview-URL
 *  kanonisieren (Begründung in app/lib/seo.js, Befund SEO-2026-W33). */
export function ladeSeite(nr, basis) {
  const daten = seite(nr);
  return {
    daten: {
      ...daten,
      folgen: daten.folgen.map((f) => ({
        ...f,
        datum: datumText(f.d),
        dauer: dauerText(f.dur),
      })),
    },
    pfade: Array.from({length: daten.seitenZahl}, (_, i) => seitenPfad(i + 1)),
    pfad: seitenPfad(daten.nr),
    schema: schemaGraph(daten, basis),
    gaeste: daten.nr === 1 ? GAESTE : [],
  };
}
